/** Derives the display status of a link (inactive > expired > exhausted > active). */
export function statusOf(link: InviteLinkDto): LinkStatus {
  if (!link.isActive) return 'inactive';
  if (link.expiresAt && new Date(link.expiresAt).getTime() < Date.now()) {
    return 'expired';
  }
  if (link.maxUses !== null && link.useCount >= link.maxUses) {
    return 'exhausted';
  }
  return 'active';
}

